    );

    const menuItems: Array<MenuItemWithSubscribedSettings | ToggleItem | DividerLineItem> = [
        {
            type: 'menuitem',
            title: config?.exporter ?? policyOwner,
            description: translate('workspace.accounting.preferredExporter'),
